import{_ as t,o,c as n,a2 as a}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/ai-change-notice.png",r="/relio/shots/en/ai-connected.png",s="/relio/shots/en/ai-first-notice.png",d="/relio/shots/en/ai-prefs.png",l="/relio/shots/en/ai-proposal-merge.png",h="/relio/shots/en/ai-tools-menu.png",c="/relio/shots/en/ai-copy-location.png",A=JSON.parse('{"title":"Working with AI","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/ai.md","filePath":"en/features/ai.md"}'),p={name:"en/features/ai.md"};function u(g,e,m,f,y,w){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="working-with-ai" tabindex="-1">Working with AI <a class="header-anchor" href="#working-with-ai" aria-label="Permalink to &quot;Working with AI&quot;">​</a></h1><p>How to ask <strong>your own AI tool</strong> — Claude Code, Claude Desktop, Cursor and others — in plain words to read Relio models, draft new models from requirement documents, and change open models.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><ul><li>You do not enter an address (URL) in your AI tool. Instead, you <strong>register the program <code>relio mcp</code> with your AI tool once</strong>. When needed, the AI tool starts <code>relio mcp</code> on your PC and talks to it (a local MCP server).</li><li>Everything happens <strong>on your PC</strong>. Relio itself has no AI, and there is no network access, no sign-in and no Relio server. Your AI tool is what answers questions and writes text.</li><li>Changes from the AI <strong>go straight into the open document in the Relio window</strong> (not saved yet). One undo takes them back, and <strong>the file changes only when you save</strong>.</li></ul><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ol><li><p><strong>Register (once)</strong> — Before starting your AI tool, paste the line below in a terminal. If <code>claude mcp list</code> shows <code>relio</code>, you are done.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --scope user relio -- relio mcp</span></span></code></pre></div><p>If <code>relio</code> is not on your PATH, see <a href="#when-relio-is-not-on-your-path">When relio is not on your PATH</a> below. You can also choose and copy this line in Tools › <strong>Command line &amp; AI connection…</strong>.</p></li><li><p><strong>Start your AI tool again</strong> — Only a newly started AI tool sees the registration. For Claude Code, run <code>claude</code> in the folder that holds your models.</p></li><li><p><strong>Your first request, inside the AI tool</strong> — For example, type:</p><blockquote><p>Use Relio to explain the tables in shop.erm</p></blockquote></li></ol><p>You usually do not have to mention Relio: for requests about <code>.erm</code> files, tables, columns or indexes, the AI tool uses Relio&#39;s tools on its own.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="_1-draft-an-erd-from-requirement-documents" tabindex="-1">① Draft an ERD from requirement documents <a class="header-anchor" href="#_1-draft-an-erd-from-requirement-documents" aria-label="Permalink to &quot;① Draft an ERD from requirement documents&quot;">​</a></h3><blockquote><p>Read the requirement documents in this folder, draft an ERD and open it in Relio</p></blockquote><p>The AI reads the documents, creates a <strong>new</strong> <code>.erm</code> draft and opens it in Relio right away. It never overwrites an existing file and does not create files outside the folders the AI tool is using. If you started the AI tool in your home folder, it first asks which project folder to use. In Claude Code you can also start with the suggested prompt <code>/mcp__relio__draft_from_requirements</code>.</p><h3 id="_2-change-an-open-model" tabindex="-1">② Change an open model <a class="header-anchor" href="#_2-change-an-open-model" aria-label="Permalink to &quot;② Change an open model&quot;">​</a></h3><blockquote><p>Add audit columns to the selected table</p></blockquote><ul><li>Select a table in the Relio window and say &quot;the selected table…&quot; — the AI knows which table you mean.</li><li>Changes from the AI go <strong>straight into the open document</strong>. If the file is not open, Relio opens it; if Relio is not running, it starts.</li><li>The changed tables are briefly highlighted and a notice such as <strong>&quot;AI changed ORDERS and 2 more [Undo] [Show changes]&quot;</strong> appears. One <strong>Undo</strong> (or <kbd>Ctrl</kbd>+<kbd>Z</kbd>) takes you back to before the AI change. If you made other edits after it, use Edit › Undo.</li><li>The document is marked unsaved. If you like the result, save it yourself (<kbd>Ctrl</kbd>+<kbd>S</kbd>).</li><li>If the change overlaps your unsaved edits, it is not applied directly; you pick in a merge tab instead. See <a href="#review-first-and-the-merge-tab">Review first and the merge tab</a> below.</li></ul><figure class="shot" data-scene="ai-change-notice"><img src="'+i+`" alt="After an AI change — highlighted tables and the notice with Undo and Show changes" loading="lazy"><figcaption>After an AI change — highlighted tables and the notice with Undo and Show changes</figcaption></figure><h3 id="_3-read-models-and-run-design-checks" tabindex="-1">③ Read models and run design checks <a class="header-anchor" href="#_3-read-models-and-run-design-checks" aria-label="Permalink to &quot;③ Read models and run design checks&quot;">​</a></h3><blockquote><p>Explain this model by business area</p></blockquote><blockquote><p>Summarize the design check results by severity</p></blockquote><p>The AI reads the model summary, tables and relationships to explain them, or runs Relio&#39;s <a href="/relio/en/features/check">design check</a> and sorts errors, warnings and notes by severity. It uses the same rules as the app&#39;s problem list. Read-only requests do not change any file.</p><h2 id="registering" tabindex="-1">Registering <a class="header-anchor" href="#registering" aria-label="Permalink to &quot;Registering&quot;">​</a></h2><h3 id="connection-scope" tabindex="-1">Connection scope <a class="header-anchor" href="#connection-scope" aria-label="Permalink to &quot;Connection scope&quot;">​</a></h3><p>Claude Code asks for a scope when you register. The scope decides <strong>in which folders Relio is connected when you start your AI tool</strong> (it is how Claude Code registers servers). It does not change which files the AI can see — see <a href="#files-the-ai-can-see">Files the AI can see</a> below.</p><table tabindex="0"><thead><tr><th>Scope</th><th>Meaning</th><th>Registration line</th></tr></thead><tbody><tr><td>In every folder <code>user</code> (recommended)</td><td>Relio is connected wherever you start your AI tool.</td><td><code>claude mcp add --scope user relio -- relio mcp</code></td></tr><tr><td>Only in this project folder <code>local</code></td><td>Paste the line in a terminal opened in that project folder.</td><td><code>claude mcp add --scope local relio -- relio mcp</code></td></tr><tr><td>With your team <code>project</code></td><td>Creates <code>.mcp.json</code> in that folder; commit it and teammates are connected too. Each teammate must install Relio and turn on the command line (<code>relio</code>), and Claude Code asks for permission the first time. Because install paths differ, it always uses the <code>relio mcp</code> form.</td><td><code>claude mcp add --scope project relio -- relio mcp</code></td></tr></tbody></table><p>Choose a scope in Tools › <strong>Command line &amp; AI connection…</strong> to copy the registration line for it.</p><h3 id="claude-desktop-·-cursor" tabindex="-1">Claude Desktop · Cursor <a class="header-anchor" href="#claude-desktop-·-cursor" aria-label="Permalink to &quot;Claude Desktop · Cursor&quot;">​</a></h3><p>Claude Desktop and Cursor are set up in a settings file, not with a terminal command. Both use the same shape.</p><table tabindex="0"><thead><tr><th>AI tool</th><th>Settings file</th></tr></thead><tbody><tr><td>Claude Desktop</td><td><code>claude_desktop_config.json</code></td></tr><tr><td>Cursor</td><td><code>.cursor/mcp.json</code></td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{ &quot;mcpServers&quot;: { &quot;relio&quot;: { &quot;command&quot;: &quot;relio&quot;, &quot;args&quot;: [&quot;mcp&quot;, &quot;--root&quot;, &quot;C:\\\\work\\\\models&quot;] } } }</span></span></code></pre></div><ul><li>These apps start <code>relio mcp</code> somewhere other than your model folder, so <strong>always give your model folder with <code>--root</code></strong>.</li><li>Inside JSON, write each <code>\\</code> twice (<code>\\\\</code>). Add options one by one to <code>args</code>.</li><li>Restart the app after registering.</li></ul><h3 id="when-relio-is-not-on-your-path" tabindex="-1">When relio is not on your PATH <a class="header-anchor" href="#when-relio-is-not-on-your-path" aria-label="Permalink to &quot;When relio is not on your PATH&quot;">​</a></h3><p>If you did not turn on <strong>&quot;Use relio from the command line&quot;</strong> when installing, or you use the portable version, <code>relio</code> is not on your PATH. Then put the full path of the executable in place of <code>relio</code>. <strong>Copy command-line path</strong> in Help › About Relio or in the Tools › Command line &amp; AI connection… window copies the full path of the executable you are running, already in quotes. <code>relio mcp --help</code> also shows the registration line for that executable when it is not on your PATH. <a href="/relio/en/features/cli#getting-started">Command line › Getting started</a></p><p>What differs by operating system is collected in the table below.</p><table tabindex="0"><thead><tr><th>Item</th><th>Windows</th></tr></thead><tbody><tr><td>Installed executable (default location)</td><td><code>%LOCALAPPDATA%\\Relio\\relio.exe</code></td></tr><tr><td>Claude Code registration</td><td><code>claude mcp add --scope user relio -- &lt;copied full path&gt; mcp</code> (the quoted path from Copy command-line path)</td></tr><tr><td><code>command</code> in a JSON settings file</td><td>Take the copied path, leave out the outer quotes and change <code>\\</code> to <code>\\\\</code> (for example <code>&quot;D:\\\\Tools\\\\Relio\\\\relio.exe&quot;</code>).</td></tr><tr><td>Turning PATH on later</td><td>Run the installer again and select the third box on its last page, <strong>&quot;Use relio from the command line&quot;</strong>. For the portable (zip) version, add its folder to PATH yourself.</td></tr><tr><td>After turning it on</td><td>Restart any terminal, Claude Desktop or Cursor that was already running so it can find <code>relio</code>.</td></tr><tr><td>Terminal opened by &quot;Open in AI tool…&quot;</td><td>Windows Terminal, or PowerShell if it is missing</td></tr></tbody></table><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><p>Put options after <code>relio mcp</code>. For example: <code>claude mcp add --scope user relio -- relio mcp --root &quot;C:\\work\\models&quot; --anonymize</code></p><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th></tr></thead><tbody><tr><td><code>--root &lt;folder&gt;</code></td><td>Adds a folder the AI can see. Repeat it for more. Without it, the folder you started the AI tool in.</td></tr><tr><td><code>--anonymize</code></td><td>Answers only with a model whose table, column and other names are replaced with numbers such as <code>T1</code> and <code>C1</code> and whose descriptions, notes and default values are empty. Types, lengths, keys, relationship structure and file names are still sent. There are no write tools.</td></tr><tr><td><code>--read-only</code></td><td>Removes the write tools (<code>create_draft</code> and <code>propose_change</code>). What the AI reads is still sent.</td></tr></tbody></table><h2 id="files-the-ai-can-see" tabindex="-1">Files the AI can see <a class="header-anchor" href="#files-the-ai-can-see" aria-label="Permalink to &quot;Files the AI can see&quot;">​</a></h2><ol><li><strong><code>.erm</code> files open in Relio</strong> — in any folder, and whichever folder you start the AI tool in, the AI can read and change them. Only that file is allowed: not other files in its folder, and no new files next to it. Once you close it in Relio, it can no longer be used.</li><li><strong>The folder you started the AI tool in</strong> and the <code>.erm</code> files under it</li><li><strong>Folders added with <code>--root</code></strong></li></ol><p>Some folders are refused. If you give one of these with <code>--root</code>, or start the AI tool in one, that folder is not allowed.</p><table tabindex="0"><thead><tr><th>Refused folders</th><th>Windows</th></tr></thead><tbody><tr><td>The top of a drive</td><td><code>C:\\</code></td></tr><tr><td>The top of your home folder and above</td><td>the top of your home folder, <code>C:\\Users</code></td></tr><tr><td>System folders and everything in them</td><td>the Windows folder, Program Files, Program Files (x86), ProgramData</td></tr><tr><td>Network folders</td><td>UNC paths, mapped network drives</td></tr></tbody></table><p><strong>If you start the AI tool in your home folder, it still connects and sees only the files open in Relio.</strong> To use a whole folder, start it again from the project folder that contains your <code>.erm</code> files, or register with <code>--root &lt;folder&gt;</code>.</p><h2 id="removing-the-registration" tabindex="-1">Removing the registration <a class="header-anchor" href="#removing-the-registration" aria-label="Permalink to &quot;Removing the registration&quot;">​</a></h2><p>Remove it for the scope you registered with. This leaves the Relio app and your files as they are.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp remove relio --scope user</span></span>
<span class="line"><span>claude mcp list</span></span></code></pre></div><p>If you registered with <code>local</code> or <code>project</code>, remove it in that project folder with <code>--scope local</code> or <code>--scope project</code>. When <code>claude mcp list</code> no longer shows <code>relio</code>, it is removed.</p><h2 id="what-you-see-in-the-window" tabindex="-1">What you see in the window <a class="header-anchor" href="#what-you-see-in-the-window" aria-label="Permalink to &quot;What you see in the window&quot;">​</a></h2><ul><li><strong>AI connected</strong> — Shows at the right of the status bar while an AI tool is connected. It soon goes away when the AI tool exits (even if it crashes).</li><li><strong>First connection notice</strong> — The first time an AI tool connects, an &quot;AI tool connection&quot; window appears once. It explains that AI changes go straight into the window and the file changes only when you save, and that what the AI reads is sent to that AI service. <strong>View guide</strong> opens this section of the in-app user guide.</li><li><strong>Apply notice</strong> — When the AI changes the model, the changed tables are briefly highlighted and a notice with <strong>Undo</strong> and <strong>Show changes</strong> appears. See <a href="#_2-change-an-open-model">② Change an open model</a> above.</li><li><strong>Reloading outside changes</strong> — While an AI is connected, if an open file changes outside (including changes by programs other than the AI tool) and you have no unsaved changes, Relio reloads it without asking. It highlights the changed tables for 3 seconds and shows a line such as &quot;AI change applied: ORDERS and 2 more&quot; in the status bar; click it to go to the table. If you have unsaved changes, it does not reload and asks with <strong>Merge…</strong> as before. <a href="/relio/en/features/file#when-you-return-to-the-window">File › When you return to the window</a></li></ul><figure class="shot" data-scene="ai-connected"><img src="`+r+'" alt="AI connected at the right of the status bar" loading="lazy"><figcaption>AI connected at the right of the status bar</figcaption></figure><figure class="shot" data-scene="ai-first-notice"><img src="'+s+'" alt="The AI tool connection notice shown on first connection" loading="lazy"><figcaption>The AI tool connection notice shown on first connection</figcaption></figure><h3 id="review-first-and-the-merge-tab" tabindex="-1">Review first and the merge tab <a class="header-anchor" href="#review-first-and-the-merge-tab" aria-label="Permalink to &quot;Review first and the merge tab&quot;">​</a></h3><p>AI changes apply right away by default, but in these cases they open in a merge tab <strong>&quot;Merge: &lt;file&gt; — AI proposal&quot;</strong> where you pick what to take and <strong>Apply</strong>:</p><ul><li>When the AI change overlaps your unsaved edits</li><li>When cell editing, dragging or a dialog goes on for more than 10 seconds (if shorter, Relio waits until you finish and then applies)</li><li>When you set <strong>AI changes</strong> to <strong>Review first</strong> in Tools › Settings › General › <strong>AI tools</strong> (the default is <strong>Apply right away</strong>) — it then always opens a merge tab</li></ul><p>In the merge tab, the base is <strong>File when the proposal was made</strong>, your side is the open document (including unsaved edits), and the other side is the AI proposal. You pick and apply items the same way as in <a href="/relio/en/features/git#merge-tab">Git and merging › Merge tab</a>. Proposal copies are kept in <code>mcp\\proposals</code> in the settings folder and deleted when the app starts after 7 days.</p><figure class="shot" data-scene="ai-prefs"><img src="'+d+'" alt="Settings › General › AI tools — Apply right away and Review first" loading="lazy"><figcaption>Settings › General › AI tools — Apply right away and Review first</figcaption></figure><figure class="shot" data-scene="ai-proposal-merge"><img src="'+l+'" alt="Merge tab — picking items from an AI proposal" loading="lazy"><figcaption>Merge tab — picking items from an AI proposal</figcaption></figure><h2 id="tools-menu" tabindex="-1">Tools menu <a class="header-anchor" href="#tools-menu" aria-label="Permalink to &quot;Tools menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Menu › Item</th><th>What it does</th></tr></thead><tbody><tr><td>Tools › Open in AI tool…</td><td>Opens a terminal in the current file&#39;s folder and shows the registration line, how to start the AI tool and a first request, ready to copy. See &quot;Open in AI tool&quot; below.</td></tr><tr><td>Tools › Command line &amp; AI connection…</td><td>Shows the connection status, how AI changes are applied, the connection scope with the lines to register and remove Relio, and the command-line status in one place. See &quot;Command line &amp; AI connection window&quot; below.</td></tr><tr><td>Tools › Copy current file path</td><td>Copies the full path of the current file, in quotes. Same as <strong>Copy path</strong> on the document tab&#39;s right-click menu.</td></tr><tr><td>Tools › Settings…</td><td><a href="/relio/en/features/preferences">Settings</a></td></tr></tbody></table><p>Open in AI tool and Copy current file path work only for saved files (they are off for new documents and sample copies).</p><figure class="shot" data-scene="ai-tools-menu"><img src="'+h+'" alt="Tools menu — Open in AI tool, Command line &amp; AI connection, Copy current file path" loading="lazy"><figcaption>Tools menu — Open in AI tool, Command line &amp; AI connection, Copy current file path</figcaption></figure><h3 id="open-in-ai-tool" tabindex="-1">Open in AI tool <a class="header-anchor" href="#open-in-ai-tool" aria-label="Permalink to &quot;Open in AI tool&quot;">​</a></h3><p>Tools › <strong>Open in AI tool…</strong> (also on the document tab&#39;s right-click menu) <strong>only opens</strong> a terminal in the folder of that <code>.erm</code>. It never runs a command for you. The &quot;Open in AI tool&quot; window shows these steps in order, each with a <strong>Copy</strong> button:</p><ol><li><strong>Paste into the terminal</strong> — the registration line (first time only). It is already on your clipboard when the window opens, and follows the scope chosen in the Command line &amp; AI connection window.</li><li><strong>Start your AI tool</strong> — for Claude Code, run <code>claude</code>.</li><li><strong>Your first request, inside the AI tool</strong> — for example &quot;Use Relio to explain the tables in &lt;file&gt;&quot;. Another example, a draft from requirement documents, is shown too.</li></ol><p>If the terminal cannot be opened, the window shows the folder path so you can open a terminal there yourself.</p><h3 id="command-line-ai-connection-window" tabindex="-1">Command line &amp; AI connection window <a class="header-anchor" href="#command-line-ai-connection-window" aria-label="Permalink to &quot;Command line &amp; AI connection window&quot;">​</a></h3><p>What you see in Tools › <strong>Command line &amp; AI connection…</strong>:</p><ul><li><strong>AI connection</strong> — the connection status (AI connected or Not connected), how AI changes are applied (Apply right away or Review first — change it in Settings › General), the connection scope (In every folder, Only in this project folder, With your team), and for the chosen scope the registration line, the line to remove it and a check that it is registered (<code>claude mcp list</code>).</li><li><strong>Command line</strong> — whether &quot;Use relio from the command line&quot; is on or off, the command-line path and <strong>Copy command-line path</strong>. When it is off, the window tells you how to turn it on (see <a href="#when-relio-is-not-on-your-path">When relio is not on your PATH</a> above).</li></ul><h3 id="passing-a-file-or-location" tabindex="-1">Passing a file or location <a class="header-anchor" href="#passing-a-file-or-location" aria-label="Permalink to &quot;Passing a file or location&quot;">​</a></h3><p>To tell the AI exactly which file or table you mean, copy it and paste it into your AI tool:</p><ul><li>Tools › <strong>Copy current file path</strong> — the current file&#39;s path</li><li>Right-click a table or view on the canvas or in the outline › <strong>Copy location for AI</strong> — one line such as <code>ORDERS table in &quot;…\\shop.erm&quot;</code></li></ul><p>With several models and no file named, the AI asks first.</p><figure class="shot" data-scene="ai-copy-location"><img src="'+c+'" alt="Copy location for AI on a table&#39;s right-click menu" loading="lazy"><figcaption>Copy location for AI on a table&#39;s right-click menu</figcaption></figure><h2 id="tools-the-ai-uses" tabindex="-1">Tools the AI uses <a class="header-anchor" href="#tools-the-ai-uses" aria-label="Permalink to &quot;Tools the AI uses&quot;">​</a></h2><p>Your AI tool picks these on its own. You do not need to call them yourself.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>list_models</code></td><td><code>.erm</code> files in the allowed folders and files open in Relio (with where each comes from)</td></tr><tr><td><code>model_summary</code></td><td>Database, counts, categories, table list, design check counts</td></tr><tr><td><code>list_tables</code></td><td>Tables and views</td></tr><tr><td><code>get_table</code></td><td>All columns, indexes and relationships of one table</td></tr><tr><td><code>find</code></td><td>Search names and descriptions (Korean initial consonants included)</td></tr><tr><td><code>related</code></td><td>Tables linked by relationships (up to depth 3)</td></tr><tr><td><code>lint</code></td><td>Design check</td></tr><tr><td><code>export_ddl</code></td><td>DDL text</td></tr><tr><td><code>diff</code></td><td>Compare with another file or a Git version</td></tr><tr><td><code>get_selection</code></td><td>The tables selected in the Relio window right now</td></tr><tr><td><code>open_in_relio</code></td><td>Open in the Relio window and highlight a table</td></tr><tr><td><code>create_draft</code></td><td>A <strong>new</strong> <code>.erm</code> draft from DBML, Mermaid or SQL, opened in Relio (never overwrites an existing file)</td></tr><tr><td><code>propose_change</code></td><td>Change an open model (applied right away, or in a merge tab)</td></tr></tbody></table><p>With <code>--read-only</code> or <code>--anonymize</code>, the write tools (<code>create_draft</code> and <code>propose_change</code>) are removed.</p><p>There are also four suggested prompts. They show up if your AI tool lets you pick from a prompt list; in Claude Code, run them as slash commands <code>/mcp__relio__&lt;name&gt;</code> (for example <code>/mcp__relio__explain_model</code>).</p><table tabindex="0"><thead><tr><th>Suggested prompt</th><th>What it does</th></tr></thead><tbody><tr><td><code>explain_model</code></td><td>Explains the model by business area — what the main tables hold and how they relate</td></tr><tr><td><code>review_ddl</code></td><td>Reviews the DDL and design and lists problems by severity</td></tr><tr><td><code>change_impact</code></td><td>Finds the tables, relationships and foreign keys a planned change touches and suggests an order of work</td></tr><tr><td><code>draft_from_requirements</code></td><td>Drafts an ERD from requirement documents</td></tr></tbody></table><h2 id="using-it-safely" tabindex="-1">Using it safely <a class="header-anchor" href="#using-it-safely" aria-label="Permalink to &quot;Using it safely&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Warning</p><ul><li>What the AI reads (table and column names and descriptions) is <strong>sent to your AI service</strong>. You are told once, the first time it connects. For company models, hide names and descriptions with <code>--anonymize</code> and narrow the folders with <code>--root</code> (<code>--read-only</code> only blocks writing, not sending).</li><li>AI changes made through Relio go only into the open document; the file changes only when you save. Relio writes only new draft files and the <code>mcp</code> folder in the settings folder.</li><li>However, apart from Relio, your AI tool <strong>can edit <code>.erm</code> files directly with its own file editing features</strong>. Keep a backup of your model folder or protect it with version control such as Git.</li><li>The AI reads <strong>saved files</strong>. It does not see what you have not saved in the window yet (that is why overlaps open in a merge tab).</li><li>There is no rename tool, so when the AI renames a table or column it may apply as a delete plus an add.</li></ul></div><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><p><strong>I registered it in a terminal, but Relio is not in the Claude desktop app&#39;s connector list.</strong> Registering with <code>claude mcp add</code> in a terminal is a Claude Code registration, so it does not show up in the desktop app&#39;s connector list. Check that it is registered with <code>claude mcp list</code> in a terminal.</p><p><strong>I registered it, but the AI tool does not use Relio.</strong> Only a newly started AI tool sees the registration. Quit the AI tool and start it again. If <code>relio</code> is not on your PATH, register with the full path as in <a href="#when-relio-is-not-on-your-path">When relio is not on your PATH</a>.</p><p><strong>I started it in my home folder and the model list is empty.</strong> Your home folder is not allowed as a whole, so only files open in Relio are visible. Start it again from the project folder that holds your models, or register with <code>--root</code>. <a href="#files-the-ai-can-see">Files the AI can see</a></p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/relio/en/features/cli">Command line</a> — Putting <code>relio</code> on your PATH, other commands</li><li><a href="/relio/en/features/git#merging">Git and merging › Merging</a> — Picking and applying in a merge tab</li><li><a href="/relio/en/features/preferences#general">Settings › General</a> — How AI changes are applied</li><li><a href="/relio/en/features/troubleshooting">Help and troubleshooting</a> — The user guide, About Relio, where your data is stored</li></ul>',85)])])}const I=t(p,[["render",u]]);export{A as __pageData,I as default};
